// 1. Captura o input atual que veio do Agente de IA / Switch de Intenção
const inputIA = $input.first().json.output;

// 2. Captura o estado da memória que foi salvo anteriormente no Redis através do nó Switch
const authControl = $('Switch').first().json.auth_control;

// Funções auxiliares de limpeza
const apenasNumeros = (txt) => txt ? txt.toString().replace(/\D/g, '') : '';
const limparTexto = (txt) => txt ? txt.toString().toLowerCase().trim() : '';

// 3. Identifica o tipo de dado que estamos validando neste momento
const tipoDadoEsperado = authControl.dado_solicitado_1; // 'cpf', 'data de nascimento' ou 'e-mail corporativo'
let isValido = false;

// 4. Executa a validação baseada no tipo de dado
if (tipoDadoEsperado === 'e-mail corporativo') {
  // Validação de E-mail: ignora maiúsculas/minúsculas e espaços
  const emailUsuario = limparTexto(inputIA.valor_extraido);
  const emailBanco = limparTexto(authControl.valor_esperado_1);

  if (emailUsuario !== '' && emailUsuario === emailBanco) {
    isValido = true;
  }
} else {
  // Validação de CPF ou Data de Nascimento: limpa pontos, barras e traços
  const numUsuario = apenasNumeros(inputIA.valor_extraido);
  const numBanco = apenasNumeros(authControl.valor_esperado_1);

  if (numUsuario !== '' && numUsuario === numBanco) {
    isValido = true;
  }
}

// 5. Retorna o resultado estruturado para os próximos nós do fluxo
return {
  dado_1_valido: isValido, // Alimenta a condição do seu nó IF de validação[cite: 1]

  // Repassa o objeto auth_control atualizado
  auth_control: {
    ...authControl,
    flag_1: isValido ? true : authControl.flag_1 // Se acertou, a flag_1 vira true
  }
};

const inputIA = $input.first().json.output;
const authControl = $('Switch').first().json.auth_control;

const apenasNumeros = (txt) => txt ? txt.toString().replace(/\D/g, '') : '';
const limparTexto = (txt) => txt ? txt.toString().toLowerCase().trim() : '';

const tipoDadoEsperado = authControl.dado_solicitado_2;
let isValido = false;

if (tipoDadoEsperado === 'e-mail corporativo') {
  const emailUsuario = limparTexto(inputIA.valor_extraido);
  const emailBanco = limparTexto(authControl.valor_esperado_2);
  if (emailUsuario !== '' && emailUsuario === emailBanco) isValido = true;
} else {
  const numUsuario = apenasNumeros(inputIA.valor_extraido);
  const numBanco = apenasNumeros(authControl.valor_esperado_2);
  if (numUsuario !== '' && numUsuario === numBanco) isValido = true;
}

// 🔹 Multi-empresa: autenticou, mas ainda falta escolher a empresa.
//    So perguntamos DEPOIS da autenticacao - antes disso seria vazar
//    o empregador de alguem para quem estiver com o telefone na mao.
const multi = String(authControl.multi_empresa).toLowerCase() === 'true';

return {
  dado_2_valido: isValido,
  precisa_escolher_empresa: isValido && multi,
  auth_control: {
    ...authControl,
    flag_2: isValido ? true : authControl.flag_2,
    aguardando_empresa: isValido ? multi : false
  }
};

// Recebe N linhas (uma por vinculo do colaborador) e decide o caminho.
// Casos: COM_VINCULO | SEM_VINCULO_ATIVO | NAO_ENCONTRADO
const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && (r.id_employee !== undefined && r.id_employee !== null && r.id_employee !== ''));

const ativos = rows.filter(r => Number(r.vinculo_ativo) === 1);

// Dedup: mesmo CPF com dois registros na MESMA empresa -> mantem so um ativo
const vistos = new Set();
const ativosUnicos = [];
for (const r of ativos) {
  const chave = String(r.company_id);
  if (vistos.has(chave)) continue;
  vistos.add(chave);
  ativosUnicos.push(r);
}

let caso = 'COM_VINCULO';
if (rows.length === 0) caso = 'NAO_ENCONTRADO';
else if (ativosUnicos.length === 0) caso = 'SEM_VINCULO_ATIVO';

const base = rows[0] || {};

return [{
  json: {
    caso,
    total_vinculos: rows.length,
    total_ativos: ativosUnicos.length,
    multi_empresa: ativosUnicos.length > 1,
    vinculos_ativos: ativosUnicos.map(r => ({
      employee_id: r.id_employee,
      company_id: r.company_id,
      empresa_nome: r.empresa_fantasia || r.empresa_nome || ('Empresa ' + r.company_id)
    })),
    // dados pessoais sao os mesmos em todos os vinculos (vem de [user])
    id_user: base.id_user,
    name: base.name,
    cpf: base.cpf,
    birthdate: base.birthdate,
    email: base.email
  }
}];

// Recebe N linhas (uma por vinculo do colaborador) e decide o caminho.
// Casos: COM_VINCULO | SEM_VINCULO_ATIVO | NAO_ENCONTRADO
const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && (r.id_employee !== undefined && r.id_employee !== null && r.id_employee !== ''));

const ativos = rows.filter(r => Number(r.vinculo_ativo) === 1);

// Dedup: mesmo CPF com dois registros na MESMA empresa -> mantem so um ativo
const vistos = new Set();
const ativosUnicos = [];
for (const r of ativos) {
  const chave = String(r.company_id);
  if (vistos.has(chave)) continue;
  vistos.add(chave);
  ativosUnicos.push(r);
}

let caso = 'COM_VINCULO';
if (rows.length === 0) caso = 'NAO_ENCONTRADO';
else if (ativosUnicos.length === 0) caso = 'SEM_VINCULO_ATIVO';

const base = rows[0] || {};

return [{
  json: {
    caso,
    total_vinculos: rows.length,
    total_ativos: ativosUnicos.length,
    multi_empresa: ativosUnicos.length > 1,
    vinculos_ativos: ativosUnicos.map(r => ({
      employee_id: r.id_employee,
      company_id: r.company_id,
      empresa_nome: r.empresa_fantasia || r.empresa_nome || ('Empresa ' + r.company_id)
    })),
    // dados pessoais sao os mesmos em todos os vinculos (vem de [user])
    id_user: base.id_user,
    name: base.name,
    cpf: base.cpf,
    birthdate: base.birthdate,
    email: base.email
  }
}];

// Le a resposta do colaborador e resolve QUAL empresa ele escolheu.
const authControl = $('Switch').first().json.auth_control;
const msg = String($('Edit Fields').first().json.mensagem || '').trim();
// 🔹 O Redis grava o auth_control como hash: todo campo volta string.
// vinculos_ativos e gravado com JSON.stringify, entao aqui desserializa.
const parseVinculos = (v) => {
  if (Array.isArray(v)) return v;
  try { return JSON.parse(v || '[]'); } catch (e) { return []; }
};

const opcoes = parseVinculos(authControl.vinculos_ativos);

const norm = (t) => String(t || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]/g, '');

let escolhida = null;

// 1) pelo numero da opcao
const num = msg.replace(/\D/g, '');
if (num && msg.length <= 3) {
  const i = Number(num);
  if (i >= 1 && i <= opcoes.length) escolhida = opcoes[i - 1];
}

// 2) pelo nome da empresa
if (!escolhida) {
  const m = norm(msg);
  if (m.length >= 3) {
    escolhida = opcoes.find(o => {
      const n = norm(o.empresa_nome);
      return n.includes(m) || m.includes(n);
    }) || null;
  }
}

const tentativas = Number(authControl.tentativas_empresa || 0) + (escolhida ? 0 : 1);

return {
  escolha_valida: !!escolhida,
  tentativas,
  auth_control: {
    ...authControl,
    tentativas_empresa: tentativas,
    aguardando_empresa: escolhida ? false : true,
    employee_id: escolhida ? escolhida.employee_id : authControl.employee_id,
    company_id: escolhida ? escolhida.company_id : authControl.company_id,
    empresa_nome: escolhida ? escolhida.empresa_nome : authControl.empresa_nome
  }
};

